head.b:skin:
/* Estilos base del sistema */

/* Lightbox: forzar oculto hasta abrir */
#lightbox { display: none !important; visibility: hidden !important; pointer-events: none !important; }
#lightbox.is-open { display: flex !important; visibility: visible !important; pointer-events: auto !important; }
#lightbox-backdrop { position: absolute; inset: 0; background: rgba(20, 18, 16, 0.88); }
#lightbox-panel { position: relative; z-index: 10; width: 100%; max-width: 64rem; max-height: 92vh; display: flex; flex-direction: column; border-radius: 1rem; border: 1px solid rgba(255,255,255,0.1); background: rgba(46, 38, 32, 0.95); overflow: hidden; }
html { scroll-behavior: smooth; }

body { font-family: system-ui, -apple-system, 'Segoe UI', sans-serif; background: #141210; color: #F0E8DA; margin: 0; }
    #inicio { min-height: 100vh; position: relative; }
    #inicio .absolute.inset-0 { position: absolute; inset: 0; }
    #inicio .absolute.inset-0 picture { display: block; width: 100%; height: 100%; }
    #inicio .absolute.inset-0 img { width: 100%; height: 100%; object-fit: cover; display: block; }
    #inicio .relative.z-10 { text-shadow: 0 2px 28px rgba(0,0,0,0.55), 0 1px 4px rgba(0,0,0,0.4); }
    .font-display { font-family: Georgia, 'Times New Roman', serif; }
    .gallery-card { transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.45s ease; }
    .gallery-card:hover { transform: translateY(-6px); box-shadow: 0 24px 48px rgba(0,0,0,0.45); }
    .nav-open #mobile-panel { max-height: 24rem; opacity: 1; }
    .nav-open #menu-icon-open { display: none; }
    .nav-open #menu-icon-close { display: block; }
    #menu-icon-close { display: none; }
    ::selection { background: rgba(201, 169, 98, 0.35); color: #fff; }
    #lightbox:not(.is-open) { display: none; }
    #lightbox.is-open { display: flex; }
    body.lightbox-open { overflow: hidden; }
    #lightbox-img { transition: opacity 0.25s ease, max-height 0.35s cubic-bezier(0.22, 1, 0.36, 1), max-width 0.35s cubic-bezier(0.22, 1, 0.36, 1); }
    #lightbox-img.is-changing { opacity: 0; }
    #lightbox-image-wrap { cursor: zoom-in; }
    #lightbox.is-image-zoomed #lightbox-image-wrap { cursor: zoom-out; }
    #lightbox-chrome-top,
    #lightbox-chrome-bottom,
    #lightbox-prev,
    #lightbox-next,
    #lightbox-zoom-hint {
      transition: opacity 0.3s ease, transform 0.3s ease;
    }
    #lightbox.is-image-zoomed #lightbox-panel {
      max-width: 100%;
      max-height: 100%;
      width: 100%;
      height: 100%;
      background: transparent;
      border-color: transparent;
      box-shadow: none;
      border-radius: 0;
      transition: background 0.3s ease, border-color 0.3s ease;
    }
    #lightbox.is-image-zoomed #lightbox-chrome-top,
    #lightbox.is-image-zoomed #lightbox-chrome-bottom,
    #lightbox.is-image-zoomed #lightbox-prev,
    #lightbox.is-image-zoomed #lightbox-next,
    #lightbox.is-image-zoomed #lightbox-zoom-hint {
      opacity: 0;
      pointer-events: none;
      transform: scale(0.96);
    }
    #lightbox.is-image-zoomed #lightbox-close {
      opacity: 0;
      pointer-events: none;
    }
    #lightbox.is-image-zoomed #lightbox-backdrop {
      background: rgba(20, 18, 16, 0.97);
    }
    #lightbox.is-image-zoomed #lightbox-stage {
      flex: 1;
      min-height: 100%;
      padding: 0;
    }
    #lightbox.is-image-zoomed #lightbox-image-wrap {
      position: fixed;
      inset: 0;
      z-index: 25;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 1.5rem;
      min-height: auto;
      max-height: none;
    }
    #lightbox.is-image-zoomed #lightbox-img {
      max-height: 96vh;
      max-width: 96vw;
      border-radius: 0.25rem;
    }
    .gallery-card { cursor: pointer; }
    .gallery-card:focus-visible { outline: 2px solid rgba(201, 169, 98, 0.6); outline-offset: 4px; }
    #lightbox-video-wrap { display: none; width: 100%; max-width: 100%; min-height: 266px; aspect-ratio: 16/9; max-height: 58vh; position: relative; z-index: 5; }
    #lightbox-video-wrap iframe { display: block; width: 100%; min-height: 266px; height: 100%; background: #141210; }
    #lightbox.is-video-slide #lightbox-image-wrap { display: none !important; }
    #lightbox.is-video-slide #lightbox-video-wrap { display: flex !important; align-items: center; justify-content: center; }
    #lightbox.is-video-slide #lightbox-zoom-hint { display: none !important; }
    #lightbox.is-video-slide.is-image-zoomed #lightbox-image-wrap { position: relative; inset: auto; padding: 0; }
    #lightbox-video-fallback { display: none; margin-top: 0.75rem; text-align: center; }
    #lightbox.is-video-slide #lightbox-video-fallback.is-visible { display: block; }
    #lightbox.is-video-slide #lightbox-video-wrap { flex-direction: column; }
    .blogger-video-shell { width: 100%; display: flex; flex-direction: column; align-items: center; gap: 1rem; }
    .blogger-video-actions { display: flex; flex-wrap: wrap; gap: 0.75rem; justify-content: center; z-index: 12; }
    .blogger-video-open-btn { display: inline-flex; align-items: center; gap: 0.5rem; padding: 0.85rem 1.5rem; border-radius: 9999px; background: rgba(201,169,98,0.92); color: #141210; font-weight: 600; font-size: 0.95rem; text-decoration: none; box-shadow: 0 8px 24px rgba(0,0,0,0.35); }
    .blogger-video-open-btn:hover { background: rgb(226, 201, 138); color: #141210; }
    .blogger-video-post-link { display: inline-flex; align-items: center; padding: 0.85rem 1.25rem; border-radius: 9999px; border: 1px solid rgba(201,169,98,0.45); color: #F5E6C8; font-size: 0.9rem; text-decoration: none; }
    .blogger-video-post-link:hover { border-color: rgba(201,169,98,0.75); color: #fff; }
    .blogger-video-hint { font-size: 0.8rem; color: hsla(40,30%,79%,0.88); text-align: center; max-width: 34rem; line-height: 1.55; margin: 0; padding: 0 0.5rem; }
    .blogger-video-iframe-wrap { width: 100%; border-radius: 0.5rem; overflow: hidden; background: #141210; }
    .gallery-card .media-play-badge { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; pointer-events: none; }
    .gallery-card .media-play-badge span { width: 3.5rem; height: 3.5rem; border-radius: 9999px; background: rgba(20,18,16,0.72); border: 1px solid rgba(201,169,98,0.35); display: flex; align-items: center; justify-content: center; color: #F5E6C8; font-size: 1.25rem; }


